import{_ as p,a0 as o,w as d,s as c,I as e,x as a,a1 as i,A as l,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"不常見但是很有用的 GCC 命令列選項（二） | LCTT x X-CMD","titleTemplate":false,"description":"不常見但是很有用的 GCC 命令列選項（二） | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"不常見但是很有用的 GCC 命令列選項（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"不常見但是很有用的 GCC 命令列選項（二） | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161201 Uncommon but useful GCC command line options - part 2","title":"不常見但是很有用的 GCC 命令列選項（二）","tag":"201612","desc":""},"relativePath":"201612/20161201 Uncommon but useful GCC command line options - part 2.md","filePath":"[post].md"}'),r={name:"201612/20161201 Uncommon but useful GCC command line options - part 2.md"};function g(u,s,h,k,b,f){const n=o("Link");return d(),c("div",null,[s[25]||(s[25]=e("h1",{id:"不常見但是很有用的-gcc-命令列選項-二",tabindex:"-1"},[a("不常見但是很有用的 GCC 命令列選項（二） "),e("a",{class:"header-anchor",href:"#不常見但是很有用的-gcc-命令列選項-二","aria-label":"Permalink to “不常見但是很有用的 GCC 命令列選項（二）”"},"​")],-1)),s[26]||(s[26]=e("p",null,"gcc 編譯器提供了幾乎數不清的命令列選項列表。當然，沒有人會使用過或者精通它所有的命令列選項，但是有一些命令列選項是每一個 gcc 用户都應該知道的 - 即使不是必須知道。它們中有一些很常用，其他一些不太常用，但不常用並不意味着它們的用處沒前者大。",-1)),e("p",null,[s[1]||(s[1]=a("在這個系列的文章中，我們集中於一些不常用但是很有用的 gcc 命令列選項，在",-1)),i(n,{href:"https://linux.cn/article-8025-1.html"},{default:l(()=>[...s[0]||(s[0]=[a("第一節",-1)])]),_:1}),s[2]||(s[2]=a("已經講到幾個這樣的命令列選項。",-1))]),s[27]||(s[27]=t(`<p>不知道你是否能夠回想起，在這個系列教程的第一部分的開始，我簡要的提到了開發者們通常用來生成警告的 <code>-Wall</code> 選項，並不包括一些特殊的警告。如果你不瞭解這些特殊警告，並且不知道如何生成它們，不用擔心，我將在這篇文章中詳細講解關於它們所有的細節。</p><p>除此以外，這篇文章也將涉及與浮點值相關的 gcc 警告選項，以及在 gcc 命令列選項列表變得很大的時候如何更好的管理它們。</p><p>在繼續之前，請記住，這個教程中的所有例子、命令和指令都已在 Ubuntu 16.04 LTS 操作系統和 gcc 5.4.0 上測試過。</p><h3 id="生成-wall-選項不包括的警告" tabindex="-1">生成 -Wall 選項不包括的警告 <a class="header-anchor" href="#生成-wall-選項不包括的警告" aria-label="Permalink to “生成 -Wall 選項不包括的警告”">​</a></h3><p>儘管 gcc 編譯器的 <code>-Wall</code> 選項涵蓋了絕大多數警告標記，依然有一些警告不能生成。為了生成它們，請使用 <code>-Wextra</code> 選項。</p><p>比如，下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int i=0;</span></span>
<span class="line"><span>    /* ...</span></span>
<span class="line"><span>       some code here </span></span>
<span class="line"><span>       ...</span></span>
<span class="line"><span>    */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if(i);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>     return 0; </span></span>
<span class="line"><span>}</span></span></code></pre></div><p>我不小心在 <code>if</code> 條件後面多打了一個分號。現在，如果使用下面的 gcc 命令來進行編譯，不會生成任何警告。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -Wall test.c -o test</span></span></code></pre></div><p>但是如果同時使用 <code>-Wextra</code> 選項來進行編譯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -Wall -Wextra test.c -o test</span></span></code></pre></div><p>會生成下面這樣一個警告：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test.c: In function ‘main’:</span></span>
<span class="line"><span>test.c:10:8: warning: suggest braces around empty body in an ‘if’ statement [-Wempty-body]</span></span>
<span class="line"><span> if(i);</span></span></code></pre></div><p>從上面的警告清楚的看到， <code>-Wextra</code> 選項從內部啓用了 <code>-Wempty-body</code> 選項，從而可以檢測可疑代碼並生成警告。下面是這個選項啓用的全部警告標記。</p><ul><li><code>-Wclobbered</code></li><li><code>-Wempty-body</code></li><li><code>-Wignored-qualifiers</code></li><li><code>-Wmissing-field-initializers</code></li><li><code>-Wmissing-parameter-type</code> （僅針對 C 語言）</li><li><code>-Wold-style-declaration</code> （僅針對 C 語言）</li><li><code>-Woverride-init</code></li><li><code>-Wsign-compare</code></li><li><code>-Wtype-limits</code></li><li><code>-Wuninitialized</code></li><li><code>-Wunused-parameter</code> （只有和 <code>-Wunused</code> 或 <code>-Wall</code> 選項使用時才會啓用）</li><li><code>-Wunused-but-set-parameter (只有和 </code>-Wunused<code>或</code>-Wall\` 選項使用時才會生成）</li></ul>`,15)),e("p",null,[s[4]||(s[4]=a("如果想對上面所提到的標記有更進一步的瞭解，請查看 ",-1)),i(n,{href:"https://linux.die.net/man/1/gcc"},{default:l(()=>[...s[3]||(s[3]=[a("gcc 手冊",-1)])]),_:1}),s[5]||(s[5]=a("。",-1))]),s[28]||(s[28]=t('<p>此外，遇到下面這些情況， <code>-Wextra</code> 選項也會生成警告：</p><ul><li>一個指針和整數 <code>0</code> 進行 <code>&lt;</code>， <code>&lt;=</code>， <code>&gt;</code>， 或 <code>&gt;=</code> 比較</li><li>（僅 C++）一個枚舉類型和一個非枚舉類型同時出現在一個條件表達式中</li><li>（僅 C++）有歧義的虛擬基底</li><li>（僅 C++）寄存器類型的數組加下標</li><li>（僅 C++）對寄存器類型的變量進行取址</li><li>（僅 C++）基類沒有在派生類的複製構建函數中進行初始化</li></ul><h3 id="浮點值的等值比較時生成警告" tabindex="-1">浮點值的等值比較時生成警告 <a class="header-anchor" href="#浮點值的等值比較時生成警告" aria-label="Permalink to “浮點值的等值比較時生成警告”">​</a></h3>',3)),e("p",null,[s[7]||(s[7]=a("你可能已經知道，浮點值不能進行確切的相等比較（如果不知道，請閲讀與浮點值比較相關的 ",-1)),i(n,{href:"https://isocpp.org/wiki/faq/newbie"},{default:l(()=>[...s[6]||(s[6]=[a("FAQ",-1)])]),_:1}),s[8]||(s[8]=a(")。但是如果你不小心這樣做了， gcc 編譯器是否會報出錯誤或警告？讓我們來測試一下：",-1))]),s[29]||(s[29]=t(`<p>下面是一段使用 <code>==</code> 運算符進行浮點值比較的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include&lt;stdio.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void compare(float x, float y)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    if(x == y)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        printf(&quot;\\n EQUAL \\n&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main(void)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    compare(1.234, 1.56789);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return 0; </span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用下面的 gcc 命令（包含 <code>-Wall</code> 和 <code>-Wextra</code> 選項）來編譯這段代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -Wall -Wextra test.c -o test</span></span></code></pre></div><p>遺憾的是，上面的命令沒有生成任何與浮點值比較相關的警告。快速看一下 gcc 手冊，在這種情形下可以使用一個專用的 <code>-Wfloat-equal</code> 選項。</p><p>下面是包含這個選項的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -Wall -Wextra -Wfloat-equal test.c -o test</span></span></code></pre></div><p>下面是這條命令產生的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test.c: In function ‘compare’:</span></span>
<span class="line"><span>test.c:5:10: warning: comparing floating point with == or != is unsafe [-Wfloat-equal]</span></span>
<span class="line"><span> if(x == y)</span></span></code></pre></div><p>正如上面你所看到的輸出那樣， <code>-Wfloat-equal</code> 選項會強制 gcc 編譯器生成一個與浮點值比較相關的警告。</p>`,10)),e("p",null,[s[10]||(s[10]=a("這兒是",-1)),i(n,{href:"https://linux.die.net/man/1/gcc"},{default:l(()=>[...s[9]||(s[9]=[a("gcc 手冊",-1)])]),_:1}),s[11]||(s[11]=a("關於這一選項的説明：",-1))]),s[30]||(s[30]=t(`<blockquote><p>這背後的想法是，有時，對程序員來説，把浮點值考慮成近似無限精確的實數是方便的。如果你這樣做，那麼你需要通過分析代碼，或者其他方式，算出這種計算方式引入的最大或可能的最大誤差，然後進行比較時（以及產生輸出時，不過這是一個不同的問題）允許這個誤差。特別要指出，不應該檢查是否相等，而應該檢查兩個值是否可能出現範圍重疊；這是用關係運算符來做的，所以等值比較可能是搞錯了。</p></blockquote><h3 id="如何更好的管理-gcc-命令列選項" tabindex="-1">如何更好的管理 gcc 命令列選項 <a class="header-anchor" href="#如何更好的管理-gcc-命令列選項" aria-label="Permalink to “如何更好的管理 gcc 命令列選項”">​</a></h3><p>如果在你使用的 gcc 命令中，命令列選項列表變得很大而且很難管理，那麼你可以把它放在一個文本文件中，然後把文件名作為 gcc 命令的一個參數。之後，你必須使用 <code>@file</code> 命令列選項。</p><p>比如，下面這行是你的 gcc 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -Wall -Wextra -Wfloat-equal test.c -o test</span></span></code></pre></div><p>然後你可以把這三個和警告相關的選項放到一個文件裏，文件名叫做 <code>gcc-options</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat gcc-options </span></span>
<span class="line"><span>-Wall -Wextra -Wfloat-equal</span></span></code></pre></div><p>這樣，你的 gcc 命令會變得更加簡潔並且易於管理：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc @gcc-options test.c -o test</span></span></code></pre></div><p>下面是 gcc 手冊關於 <code>@file</code> 的説明：</p><blockquote><p>從文件中讀取命令列選項。讀取到的選項隨之被插入到原始 <code>@file</code> 選項所在的位置。如果文件不存在或者無法讀取，那麼這個選項就會被當成文字處理，而不會被刪除。</p></blockquote><blockquote><p>文件中的選項以空格分隔。選項中包含空白字符的話，可以用一個由單引號或雙引號包圍完整選項。任何字符（包括反斜槓: &#39;&#39;）均可能通過一個 &#39;&#39; 前綴而包含在一個選項中。如果該文件本身包含額外的 <code>@file</code> 選項，那麼它將會被遞歸處理。</p></blockquote><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這個系列的教程中，我們一共講解了 5 個不常見但是很有用的 gcc 命令列選項： <code>-Save-temps</code>、<code>-g</code>、 <code>-Wextra</code>、<code>-Wfloat-equal</code> 以及 <code>@file</code>。記得花時間練習使用每一個選項，同時不要忘了瀏覽 gcc 手冊上面所提供的關於它們的全部細節。</p><p>你是否知道或使用其他像這樣有用的 gcc 命令列選項，並希望把它們在全世界範圍內分享？請在下面的評論區留下所有的細節。</p><hr>`,16)),e("p",null,[s[13]||(s[13]=a("via: ",-1)),i(n,{href:"https://www.howtoforge.com/tutorial/uncommon-but-useful-gcc-command-line-options-2/"},{default:l(()=>[...s[12]||(s[12]=[a("https://www.howtoforge.com/tutorial/uncommon-but-useful-gcc-command-line-options-2/",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=a("作者：",-1)),i(n,{href:"https://twitter.com/howtoforgecom"},{default:l(()=>[...s[14]||(s[14]=[a("Ansh",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),i(n,{href:"https://github.com/ucasFL"},{default:l(()=>[...s[15]||(s[15]=[a("ucasFL",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),i(n,{href:"https://github.com/jasminepeng"},{default:l(()=>[...s[16]||(s[16]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[s[22]||(s[22]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const W=p(r,[["render",g]]);export{y as __pageData,W as default};
